import { type NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { loginRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const bodySchema = z.object({
  email: z.string().email('Enter a valid email'),
  password: z.string().min(1, 'Password is required'),
})

export async function POST(request: NextRequest) {
  // Rate limit by IP
  const ip =
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'

  const { success, limit, remaining } = await loginRatelimit.limit(ip)
  if (!success) {
    return new Response('Too many login attempts. Try again later.', {
      status: 429,
      headers: {
        'Retry-After': '60',
        'X-RateLimit-Limit': String(limit),
        'X-RateLimit-Remaining': '0',
      },
    })
  }

  // Validate body
  const raw = await request.json().catch(() => null)
  const parsed = bodySchema.safeParse(raw)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.format() }, { status: 400 })
  }

  const supabase = await createClient()
  const { data, error } = await supabase.auth.signInWithPassword({
    email: parsed.data.email,
    password: parsed.data.password,
  })

  if (error) {
    logger.warn({ ip, errorCode: error.status }, 'auth.login.failed')
    // Return generic message — never reveal whether email exists
    return Response.json(
      { error: 'Incorrect email or password' },
      {
        status: 401,
        headers: {
          'X-RateLimit-Limit': String(limit),
          'X-RateLimit-Remaining': String(remaining),
        },
      }
    )
  }

  logger.info({ userId: data.user?.id }, 'auth.login.success')
  return Response.json({ ok: true })
}

import { type NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { signupRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const bodySchema = z.object({
  email: z.string().email('Enter a valid email'),
  password: z.string().min(8, 'Use 8 or more characters'),
  studioName: z.string().min(2, 'Studio name must be at least 2 characters').max(60),
})

export async function POST(request: NextRequest) {
  // Rate limit by IP
  const ip =
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'

  const { success, limit, remaining } = await signupRatelimit.limit(ip)
  if (!success) {
    return new Response('Too many signup attempts. Try again later.', {
      status: 429,
      headers: {
        'Retry-After': '60',
        'X-RateLimit-Limit': String(limit),
        'X-RateLimit-Remaining': '0',
      },
    })
  }

  // Validate body
  const raw = await request.json().catch(() => null)
  const parsed = bodySchema.safeParse(raw)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.format() }, { status: 400 })
  }

  const appUrl =
    process.env.NEXT_PUBLIC_APP_URL ??
    request.headers.get('origin') ??
    'http://localhost:3100'

  const supabase = await createClient()
  const { data, error } = await supabase.auth.signUp({
    email: parsed.data.email,
    password: parsed.data.password,
    options: {
      data: {
        studio_name: parsed.data.studioName,
        full_name: parsed.data.studioName,
      },
      emailRedirectTo: `${appUrl}/auth/callback`,
    },
  })

  if (error) {
    logger.warn({ ip, errorCode: error.status }, 'auth.signup.failed')
    return Response.json(
      { error: error.message },
      {
        status: 400,
        headers: {
          'X-RateLimit-Limit': String(limit),
          'X-RateLimit-Remaining': String(remaining),
        },
      }
    )
  }

  logger.info({ userId: data.user?.id }, 'auth.signup.success')
  return Response.json({ ok: true })
}

import { type NextRequest } from 'next/server'
import { z } from 'zod'
