'use client'

import { useQuery } from '@tanstack/react-query'
import { queryKeys } from '@/lib/query-keys'
import type { DashboardKpisResponse } from '@/app/api/dashboard/kpis/route'

export type { DashboardKpisResponse as DashboardKpis }

async function fetchDashboardKpis(): Promise<DashboardKpisResponse> {
  const res = await fetch('/api/dashboard/kpis')
  if (!res.ok) throw new Error('Failed to fetch KPIs')
  return res.json() as Promise<DashboardKpisResponse>
}

export function useDashboardKpis(enabled: boolean) {
  return useQuery({
    queryKey: queryKeys.dashboard.kpis(),
    queryFn: () => fetchDashboardKpis(),
    enabled,
    staleTime: 60_000,
    retry: 1,
    // Return placeholder data so the UI always renders
    placeholderData: {
      todayBookings: 0,
      todayBookingsSubtext: 'No data yet',
      weekRevenue: 0,
      weekRevenueSubtext: 'No data yet',
      activeClients: 0,
      activeClientsSubtext: 'No data yet',
      noShowRate: 0,
      noShowRateSubtext: 'No data yet',
      depositsCollected: 0,
      depositsSubtext: 'No data yet',
      upcomingAppointments: 0,
      upcomingSubtext: 'No data yet',
    } satisfies DashboardKpisResponse,
  })
}

